/// The document instance, driven through `slab-kernel`.
pub struct Doc {
    /// Raw kernel instance for advanced integrations.
    pub inst: Instance,
    /// Embedded image bytes, parallel to the document image tables.
    pub imgs: Vec<Vec<u8>>,
}

impl Default for Doc {
    fn default() -> Self {
        Self::new()
    }
}

impl Doc {
    /// Create an instance initialized from the embedded document.
    pub fn new() -> Doc {
        let (doc, imgs) = slab_slir::decode_doc(SLIR).expect("embedded SLIR");
        let mut inst = kframe::inst_shell();
        inst.doc = doc;
        kframe::inst_init(&mut inst);
        Doc { inst, imgs }
    }

    /// Whether the embedded document decoded successfully.
    pub fn ok(&self) -> bool {
        self.inst.ok
    }

    /// Env for the gpu client (client code 1); portrait derives from vw < vh.
    pub fn set_env(&mut self, vw: f64, vh: f64, dark: bool, coarse: bool) {
        kframe::inst_set_env(&mut self.inst, vw, vh, 1, dark, coarse);
    }

    /// Select a compiler-declared theme; an empty name restores authored values.
    pub fn set_theme(&mut self, name: &str) -> bool {
        kframe::inst_set_theme(&mut self.inst, name)
    }

    /// Move focus to a keyed focusable node; an empty key clears focus.
    /// `visible` shows the keyboard-grade focus ring.
    pub fn set_focus(&mut self, key: &str, visible: bool) -> bool {
        kframe::inst_set_focus(&mut self.inst, key, visible)
    }

    /// Replace a keyed field buffer, reset its edit history, and emit Change.
    pub fn set_field_text(&mut self, key: &str, text: &str) -> bool {
        kframe::inst_set_field_text(&mut self.inst, key, text)
    }

    /// Return a keyed field's committed text, or `None` for a non-field key.
    pub fn field_text(&self, key: &str) -> Option<String> {
        kframe::inst_field_text(&self.inst, key)
    }

    /// Current theme name; empty means the authored base.
    pub fn theme(&self) -> String {
        kframe::inst_theme(&self.inst)
    }

    /// Solve and flatten the document at `t_ms` milliseconds.
    pub fn frame(&mut self, t_ms: f64) -> Frame {
        kframe::inst_frame(&mut self.inst, t_ms)
    }

    /// Return the current host-content hole rectangles.
    pub fn holes(&mut self) -> Vec<HoleRect> {
        kframe::inst_holes(&mut self.inst)
    }

    /// Set a keyed scroll node's offset on axis 0 (main) or 1 (cross).
    pub fn set_scroll(&mut self, key: &str, axis: u32, off: f64) -> bool {
        kframe::inst_set_scroll(&mut self.inst, key, axis, off)
    }

    /// Read a keyed scroll node's offset on axis 0 (main) or 1 (cross).
    pub fn get_scroll(&self, key: &str, axis: u32) -> f64 {
        kframe::inst_get_scroll(&self.inst, key, axis)
    }

    /// Register or replace a named runtime image and return its unified image index.
    pub fn img_register(&mut self, name: &str, w: u32, h: u32, format: u32, data: &[u8]) -> i32 {
        kframe::inst_img_register(&mut self.inst, name, w, h, format, data)
    }

    /// Unregister a named runtime image while preserving its unified image index.
    pub fn img_unregister(&mut self, name: &str) -> bool {
        kframe::inst_img_unregister(&mut self.inst, name)
    }

    /// Scroll ancestors minimally to reveal a keyed node with the requested margin.
    pub fn reveal(&mut self, key: &str, margin: f64) -> bool {
        kframe::inst_reveal(&mut self.inst, key, margin)
    }

    /// Reveal an item in a virtual list using start, center, end, or nearest alignment.
    pub fn reveal_item(&mut self, each_key: &str, index: i32, align: u32) -> bool {
        kframe::inst_reveal_item(&mut self.inst, each_key, index, align)
    }

    /// Return a virtual list's materialized half-open item window.
    pub fn each_window(&self, each_key: &str) -> (i32, i32) {
        kframe::inst_each_window(&self.inst, each_key)
    }

    /// Set the extent overlay controlled by a keyed divider.
    pub fn set_divider(&mut self, key: &str, extent: f64) -> bool {
        kframe::inst_set_divider(&mut self.inst, key, extent)
    }

    /// Read a keyed divider's extent overlay, or `-1.0` when unknown or unset.
    pub fn get_divider(&self, key: &str) -> f64 {
        kframe::inst_get_divider(&self.inst, key)
    }

    /// Dispatch an input event and return its raw and typed effects.
    pub fn dispatch(&mut self, ev: &Event) -> (Effects, Vec<Signal>) {
        let eff = kframe::inst_dispatch(&mut self.inst, ev);
        let sigs = self.decode_signals(&eff);
        (eff, sigs)
    }

    /// Drain solve-time signals queued by the most recent frame.
    pub fn take_signals(&mut self) -> (Effects, Vec<Signal>) {
        let eff = kframe::inst_take_signals(&mut self.inst);
        let sigs = self.decode_signals(&eff);
        (eff, sigs)
    }

    /// Decode Effects signal refs against the document's STRS pool.
    pub fn decode_signals(&self, eff: &Effects) -> Vec<Signal> {
        let mut out = Vec::new();
        for (i, &name) in eff.sig_name.iter().enumerate() {
            match name {
                SIG_SAVE => out.push(Signal::Save {
                    item: eff.sig_item[i].clone(),
                    meta: SignalMeta::from(&eff.sig_meta[i]),
                }),
                SIG_RESET => out.push(Signal::Reset {
                    item: eff.sig_item[i].clone(),
                    meta: SignalMeta::from(&eff.sig_meta[i]),
                }),
                SIG_SORT => out.push(Signal::Sort {
                    item: eff.sig_item[i].clone(),
                    meta: SignalMeta::from(&eff.sig_meta[i]),
                }),
                SIG_DRAFT => out.push(Signal::Draft {
                    text: eff.sig_text[i].clone(),
                    item: eff.sig_item[i].clone(),
                    meta: SignalMeta::from(&eff.sig_meta[i]),
                }),
                _ => {}
            }
        }
        out
    }

    /// Set param `title` (text); false = rejected by the kernel.
    pub fn set_title(&mut self, v: &str) -> bool {
        let mut pv = ParamValue {
            kind: 0,
            num: 0.0,
            s: String::new(),
            rgba: 0,
            sym: String::new(),
        };
        pv.s = v.to_string();
        kframe::inst_set_param(&mut self.inst, 0, &pv)
    }

    /// Set param `status` (text); false = rejected by the kernel.
    pub fn set_status(&mut self, v: &str) -> bool {
        let mut pv = ParamValue {
            kind: 0,
            num: 0.0,
            s: String::new(),
            rgba: 0,
            sym: String::new(),
        };
        pv.s = v.to_string();
        kframe::inst_set_param(&mut self.inst, 1, &pv)
    }

    /// Set param `draft` (text); false = rejected by the kernel.
    pub fn set_draft(&mut self, v: &str) -> bool {
        let mut pv = ParamValue {
            kind: 0,
            num: 0.0,
            s: String::new(),
            rgba: 0,
            sym: String::new(),
        };
        pv.s = v.to_string();
        kframe::inst_set_param(&mut self.inst, 2, &pv)
    }

    /// Set param `compact` (bool); false = rejected by the kernel.
    pub fn set_compact(&mut self, v: bool) -> bool {
        let mut pv = ParamValue {
            kind: 4,
            num: 0.0,
            s: String::new(),
            rgba: 0,
            sym: String::new(),
        };
        pv.num = if v { 1.0 } else { 0.0 };
        kframe::inst_set_param(&mut self.inst, 3, &pv)
    }
}
